<h2 class="h4 mb-3">订单管理</h2>
<form class="row g-2 mb-3" method="get"><div class="col-md-4"><input class="form-control" name="kw" value="<?=h(isset($_GET['kw']) ? $_GET['kw'] : '')?>" placeholder="订单号、标题、用户"></div><div class="col-md-2"><select class="form-select" name="status"><option value="">全部状态</option><?php foreach (\app\common\service\OrderAdminService::$statuses as $k => $v): ?><option value="<?=h($k)?>" <?=isset($_GET['status']) && $_GET['status'] == $k ? 'selected' : ''?>><?=h($v)?></option><?php endforeach; ?></select></div><div class="col-auto"><button class="btn btn-primary">筛选</button></div></form>
<div class="table-responsive table-card"><table class="table table-hover align-middle"><thead><tr><th>订单号</th><th>用户</th><th>类型</th><th>金额</th><th>状态</th><th>交付</th><th>时间</th><th>操作</th></tr></thead><tbody><?php foreach ($list as $r): ?><tr><td class="mono"><?=h($r['order_no'])?></td><td><?=h($r['username'] ?: $r['email'])?></td><td><?=h(order_type_name($r['type']))?></td><td><?=h(money($r['pay_amount']))?></td><td><?=order_status_badge($r)?></td><td><?=$r['deliver_status'] !== '' ? status_badge($r['deliver_status'], 'deliver') : ''?> <span class="small text-muted"><?=h(deliver_msg_text($r['deliver_msg']))?></span></td><td><?=h(fmt_time($r['create_time']))?></td><td><a class="btn btn-sm btn-outline-primary" href="<?=h(url_to('admin/order/detail', array('id' => $r['id'])))?>">详情</a> <a class="btn btn-sm btn-outline-secondary" href="<?=h(url_to('admin/order/edit', array('id' => $r['id'])))?>">编辑</a></td></tr><?php endforeach; ?><?php if (empty($list)): ?><tr><td colspan="8" class="text-center text-muted">暂无订单</td></tr><?php endif; ?></tbody></table></div><?=pager_html($total, $page, $size, isset($_GET) ? $_GET : array())?>
